ALTER TABLE fail2ban_settings ADD CONSTRAINT fail2ban_settings_findtime_check CHECK (findtime >= 10 AND findtime <= 31536000);
ALTER TABLE fail2ban_settings ADD CONSTRAINT fail2ban_settings_maxretry_check CHECK (maxretry >= 1 AND maxretry <= 100);
